//! Conservative, output-backed claims of complete neutral arena preservation.
//!
//! Synthesis can change native topology layout and optional metadata. Rather
//! than infer preservation from entity counts or successful encoding, decode
//! the newly generated bytes once and compare complete typed records. This
//! costs one additional bounded decode per plan, without reading source bytes.
//! A failed decode, reordered arena, missing identity, or changed value leaves
//! the existing `Reported` disposition in place.

use std::collections::{BTreeMap, BTreeSet};

use cadmpeg_core::decode::{DecodeContext, View};
use cadmpeg_core::CodecError;
use cadmpeg_ir::codec::write::{ArenaDisposition, ArenaDispositions};
use cadmpeg_ir::codec::Codec;
use cadmpeg_ir::schema::rewrite::{self, typed::RewriteIdentities};
use cadmpeg_ir::CadIr;
use serde::Serialize;
use serde_json::Value;

pub(super) fn verified(ctx: &DecodeContext<'_>, ir: &CadIr, bytes: &[u8]) -> ArenaDispositions {
    let mut coverage = super::COVERAGE;
    let Ok(decoded) = crate::RhinoCodec.decode_with_context(ctx, View::over_retained(bytes)) else {
        return coverage;
    };
    let output = decoded.ir();
    let Some(ids) = ordinal_identities(ir, output) else {
        return coverage;
    };
    // One injective map is shared by every arena, including references into
    // geometry arenas that remain Reported. Ordinary strings are not remapped.
    macro_rules! verify {
        ($($field:ident),+ $(,)?) => {$({
            if agrees(ctx, &ir.model.$field, &output.model.$field, &ids) {
                coverage.$field = ArenaDisposition::Written;
            }
        })+};
    }
    verify!(
        bodies,
        regions,
        shells,
        faces,
        loops,
        coedges,
        edges,
        vertices,
        points,
        surfaces,
        curves,
        pcurves,
        tessellations,
        procedural_curves,
    );
    coverage
}

/// Matching ordinal rows provide a deliberately conservative proposed map.
/// Every accepted mapping is globally injective; counts alone prove nothing.
fn ordinal_identities(left: &CadIr, right: &CadIr) -> Option<BTreeMap<String, String>> {
    let left = serde_json::to_value(&left.model).ok()?;
    let right = serde_json::to_value(&right.model).ok()?;
    let mut ids = BTreeMap::new();
    let mut targets = BTreeSet::new();
    for (name, records) in left.as_object()? {
        let (Some(records), Some(output)) = (records.as_array(), right.get(name)?.as_array())
        else {
            continue;
        };
        if records.len() != output.len() {
            continue;
        }
        for (record, output) in records.iter().zip(output) {
            let source = record.get("id")?.as_str()?;
            let target = output.get("id")?.as_str()?;
            if ids.insert(source.to_owned(), target.to_owned()).is_some()
                || !targets.insert(target.to_owned())
            {
                return None;
            }
        }
    }
    Some(ids)
}

fn agrees<T: Clone + Serialize + RewriteIdentities>(
    ctx: &DecodeContext<'_>,
    left: &[T],
    right: &[T],
    ids: &BTreeMap<String, String>,
) -> bool {
    // Empty arenas do not need a new coverage claim. This also keeps the
    // no-edit conformance assertion meaningful for populated Written arenas.
    if left.is_empty() || left.len() != right.len() {
        return false;
    }
    let rewritten = rewrite::identities(ctx, left.to_vec(), |id| {
        ids.get(id)
            .cloned()
            .ok_or_else(|| CodecError::UnsupportedContent("unmapped synthesized identity".into()))
    });
    let Ok(rewritten) = rewritten else {
        return false;
    };
    match (serde_json::to_value(rewritten), serde_json::to_value(right)) {
        (Ok(left), Ok(right)) => same_values(&left, &right),
        _ => false,
    }
}

/// Numeric JSON values use the shared geometric tolerance. All text, including
/// numeric-looking names and metadata, remains literal document content.
fn same_values(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Number(_), Value::Number(_)) => {
            cadmpeg_ir::compare::values_agree(left, right).is_ok()
        }
        (Value::Array(left), Value::Array(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .zip(right)
                    .all(|(left, right)| same_values(left, right))
        }
        (Value::Object(left), Value::Object(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .all(|(key, left)| right.get(key).is_some_and(|right| same_values(left, right)))
        }
        _ => left == right,
    }
}

